package com.client.multichatwindows.config.ui; import com.client.multichatwindows.config.ConfigManager; import net.minecraft.client.*; import net.minecraft.client.gui.*; import net.minecraft.client.gui.screen.Screen; import net.minecraft.client.gui.widget.TextFieldWidget; import net.minecraft.text.Text; public class AddServerScreen extends ScrollableDarkScreen { private final Screen parent; private TextFieldWidget ipField; private Text error=Text.empty(); public AddServerScreen(Screen parent){super(Text.translatable("multichatwindows.add_server.title"));this.parent=parent;} @Override protected void init(){clearChildren();int cx=width/2;ipField=new TextFieldWidget(textRenderer,cx-100,60,200,20,Text.translatable("multichatwindows.add_server.ip"));addDrawableChild(ipField);addDrawableChild(new DarkButton(cx-100,90,200,20,Text.translatable("multichatwindows.add_server.create"),()->{String key=ipField.getText()==null?"":ipField.getText().trim();if(key.isEmpty()){error=Text.translatable("multichatwindows.add_server.error_empty");return;}ConfigManager.getOrCreateServer(key);ConfigManager.saveServer(key);MinecraftClient.getInstance().setScreen(new TabsScreen(parent,key));}));addDrawableChild(new DarkButton(cx-100,height-28,200,20,Text.translatable("multichatwindows.back"),()->MinecraftClient.getInstance().setScreen(parent)));} @Override public void render(DrawContext ctx,int mouseX,int mouseY,float delta){super.render(ctx,mouseX,mouseY,delta);ctx.drawCenteredTextWithShadow(textRenderer,Text.translatable("multichatwindows.add_server.title"),width/2,14,0xFFFFFFFF);if(!error.getString().isEmpty())ctx.drawCenteredTextWithShadow(textRenderer,error,width/2,40,0xFFFF8080);} }
